// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Authenticate a user
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Revoke the current authentication session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Get the authenticated user
	// (GET /auth/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// Refresh an authentication session
	// (POST /auth/refresh)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// Search or list customers in the authenticated business
	// (GET /customers)
	ListCustomers(ctx context.Context, request ListCustomersRequestObject) (ListCustomersResponseObject, error)
	// Create a customer in the authenticated business
	// (POST /customers)
	CreateCustomer(ctx context.Context, request CreateCustomerRequestObject) (CreateCustomerResponseObject, error)
	// Deactivate a customer without deleting order references
	// (DELETE /customers/{customerId})
	DeactivateCustomer(ctx context.Context, request DeactivateCustomerRequestObject) (DeactivateCustomerResponseObject, error)
	// Get an active customer in the authenticated business
	// (GET /customers/{customerId})
	GetCustomer(ctx context.Context, request GetCustomerRequestObject) (GetCustomerResponseObject, error)
	// Update an active customer
	// (PUT /customers/{customerId})
	UpdateCustomer(ctx context.Context, request UpdateCustomerRequestObject) (UpdateCustomerResponseObject, error)
	// List paginated order history for a customer
	// (GET /customers/{customerId}/orders)
	GetCustomerOrderHistory(ctx context.Context, request GetCustomerOrderHistoryRequestObject) (GetCustomerOrderHistoryResponseObject, error)
	// List expense categories in the authenticated business
	// (GET /expense-categories)
	ListExpenseCategories(ctx context.Context, request ListExpenseCategoriesRequestObject) (ListExpenseCategoriesResponseObject, error)
	// Create an expense category
	// (POST /expense-categories)
	CreateExpenseCategory(ctx context.Context, request CreateExpenseCategoryRequestObject) (CreateExpenseCategoryResponseObject, error)
	// Get an expense category
	// (GET /expense-categories/{categoryId})
	GetExpenseCategory(ctx context.Context, request GetExpenseCategoryRequestObject) (GetExpenseCategoryResponseObject, error)
	// Update or deactivate an expense category
	// (PUT /expense-categories/{categoryId})
	UpdateExpenseCategory(ctx context.Context, request UpdateExpenseCategoryRequestObject) (UpdateExpenseCategoryResponseObject, error)
	// List expenses, defaulting to today in Asia/Jakarta
	// (GET /expenses)
	ListExpenses(ctx context.Context, request ListExpensesRequestObject) (ListExpensesResponseObject, error)
	// Record an expense
	// (POST /expenses)
	CreateExpense(ctx context.Context, request CreateExpenseRequestObject) (CreateExpenseResponseObject, error)
	// Get an expense in the authenticated business and outlet scope
	// (GET /expenses/{expenseId})
	GetExpense(ctx context.Context, request GetExpenseRequestObject) (GetExpenseResponseObject, error)
	// Update an expense using optimistic concurrency
	// (PUT /expenses/{expenseId})
	UpdateExpense(ctx context.Context, request UpdateExpenseRequestObject) (UpdateExpenseResponseObject, error)
	// Compatibility readiness check
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// Check whether the HTTP process is live
	// (GET /livez)
	GetLiveness(ctx context.Context, request GetLivenessRequestObject) (GetLivenessResponseObject, error)
	// List orders available to the authenticated user
	// (GET /orders)
	ListOrders(ctx context.Context, request ListOrdersRequestObject) (ListOrdersResponseObject, error)
	// Create an order and allocate an invoice atomically
	// (POST /orders)
	CreateOrder(ctx context.Context, request CreateOrderRequestObject) (CreateOrderResponseObject, error)
	// Get an order and its immutable item snapshots
	// (GET /orders/{orderId})
	GetOrder(ctx context.Context, request GetOrderRequestObject) (GetOrderResponseObject, error)
	// Cancel an unpaid order and retain it as soft-deleted history
	// (POST /orders/{orderId}/cancel)
	CancelOrder(ctx context.Context, request CancelOrderRequestObject) (CancelOrderResponseObject, error)
	// List payment receipts and outstanding balance for an order
	// (GET /orders/{orderId}/payments)
	ListOrderPayments(ctx context.Context, request ListOrderPaymentsRequestObject) (ListOrderPaymentsResponseObject, error)
	// Record a confirmed cash, BCA transfer, or QRIS receipt
	// (POST /orders/{orderId}/payments)
	RecordOrderPayment(ctx context.Context, request RecordOrderPaymentRequestObject) (RecordOrderPaymentResponseObject, error)
	// Void an erroneous confirmed receipt entry
	// (POST /orders/{orderId}/payments/{paymentId}/void)
	VoidOrderPayment(ctx context.Context, request VoidOrderPaymentRequestObject) (VoidOrderPaymentResponseObject, error)
	// Advance an order through its allowed lifecycle
	// (PATCH /orders/{orderId}/status)
	TransitionOrderStatus(ctx context.Context, request TransitionOrderStatusRequestObject) (TransitionOrderStatusResponseObject, error)
	// Get append-only status history for an order
	// (GET /orders/{orderId}/status-history)
	GetOrderStatusHistory(ctx context.Context, request GetOrderStatusHistoryRequestObject) (GetOrderStatusHistoryResponseObject, error)
	// List outlets in the authenticated business
	// (GET /outlets)
	ListOutlets(ctx context.Context, request ListOutletsRequestObject) (ListOutletsResponseObject, error)
	// Create an outlet in the authenticated business
	// (POST /outlets)
	CreateOutlet(ctx context.Context, request CreateOutletRequestObject) (CreateOutletResponseObject, error)
	// Get a business outlet
	// (GET /outlets/{outletId})
	GetOutlet(ctx context.Context, request GetOutletRequestObject) (GetOutletResponseObject, error)
	// Update an outlet profile or active state
	// (PUT /outlets/{outletId})
	UpdateOutlet(ctx context.Context, request UpdateOutletRequestObject) (UpdateOutletResponseObject, error)
	// Search perfumes in the authenticated business
	// (GET /perfumes)
	ListPerfumes(ctx context.Context, request ListPerfumesRequestObject) (ListPerfumesResponseObject, error)
	// Create a perfume catalog entry
	// (POST /perfumes)
	CreatePerfume(ctx context.Context, request CreatePerfumeRequestObject) (CreatePerfumeResponseObject, error)
	// Soft-delete a perfume while retaining order references
	// (DELETE /perfumes/{perfumeId})
	DeletePerfume(ctx context.Context, request DeletePerfumeRequestObject) (DeletePerfumeResponseObject, error)
	// Get a perfume in the authenticated business
	// (GET /perfumes/{perfumeId})
	GetPerfume(ctx context.Context, request GetPerfumeRequestObject) (GetPerfumeResponseObject, error)
	// Update a perfume and its active state
	// (PUT /perfumes/{perfumeId})
	UpdatePerfume(ctx context.Context, request UpdatePerfumeRequestObject) (UpdatePerfumeResponseObject, error)
	// List available action grants
	// (GET /permissions)
	ListPermissions(ctx context.Context, request ListPermissionsRequestObject) (ListPermissionsResponseObject, error)
	// Check whether the API is ready to serve database-backed requests
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// Search and filter services in the authenticated business
	// (GET /services)
	ListServices(ctx context.Context, request ListServicesRequestObject) (ListServicesResponseObject, error)
	// Create a business-shared service
	// (POST /services)
	CreateService(ctx context.Context, request CreateServiceRequestObject) (CreateServiceResponseObject, error)
	// Soft-delete a service without removing historical references
	// (DELETE /services/{serviceId})
	DeleteService(ctx context.Context, request DeleteServiceRequestObject) (DeleteServiceResponseObject, error)
	// Get a service in the authenticated business
	// (GET /services/{serviceId})
	GetService(ctx context.Context, request GetServiceRequestObject) (GetServiceResponseObject, error)
	// Replace editable fields and activate or deactivate a service
	// (PUT /services/{serviceId})
	UpdateService(ctx context.Context, request UpdateServiceRequestObject) (UpdateServiceResponseObject, error)
	// List users in the authenticated business
	// (GET /staff)
	ListStaff(ctx context.Context, request ListStaffRequestObject) (ListStaffResponseObject, error)
	// Create a LAUNDRY_STAFF account and assign active outlets
	// (POST /staff)
	CreateStaff(ctx context.Context, request CreateStaffRequestObject) (CreateStaffResponseObject, error)
	// Get a staff account, active outlet assignments, and action grants
	// (GET /staff/{userId})
	GetStaff(ctx context.Context, request GetStaffRequestObject) (GetStaffResponseObject, error)
	// Update staff profile or active state
	// (PUT /staff/{userId})
	UpdateStaff(ctx context.Context, request UpdateStaffRequestObject) (UpdateStaffResponseObject, error)
	// Replace a staff member's active outlet assignments
	// (PUT /staff/{userId}/outlets)
	ReplaceStaffOutlets(ctx context.Context, request ReplaceStaffOutletsRequestObject) (ReplaceStaffOutletsResponseObject, error)
	// Replace a staff member's explicit action grants
	// (PUT /staff/{userId}/permissions)
	ReplaceStaffPermissions(ctx context.Context, request ReplaceStaffPermissionsRequestObject) (ReplaceStaffPermissionsResponseObject, error)
}

type StrictHandlerFunc func(ctx echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

